module lfsr_4bit (
    input        clk,
    input        rst,
    input        en,
    output [3:0] out
);
    reg [3:0] state;
    wire feedback = state[3] ^ state[0];

    always_ff @(posedge clk) begin
        if (rst)
            state <= 4'b0001;
        else if (en)
            state <= {state[2:0], feedback};
    end

    assign out = state;
endmodule

module adder_8bit_cla (
    input  [7:0] A, B,
    input        Cin,
    output [7:0] Sum,
    output       Cout
);
    wire [7:0] g = A & B;
    wire [7:0] p = A ^ B;
    wire [8:0] c;
    assign c[0] = Cin;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : cla
            assign c[i+1] = g[i] | (p[i] & c[i]);
            assign Sum[i] = p[i] ^ c[i];
        end
    endgenerate

    assign Cout = c[8];
endmodule

