module fifo_sync_8x8 (
    input        clk,
    input        rst,
    input        wr_en,
    input        rd_en,
    input  [7:0] din,
    output [7:0] dout,
    output       full,
    output       empty
);
    reg [7:0] mem [0:7];
    reg [2:0] wr_ptr, rd_ptr;
    reg [3:0] count;

    always_ff @(posedge clk) begin
        if (rst) begin
            wr_ptr <= 3'd0;
            rd_ptr <= 3'd0;
            count  <= 4'd0;
        end else begin
            if (wr_en && !full) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 3'd1;
                count <= count + 4'd1;
            end
            if (rd_en && !empty) begin
                rd_ptr <= rd_ptr + 3'd1;
                count <= count - 4'd1;
            end
        end
    end

    assign dout  = mem[rd_ptr];
    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);
endmodule

