module debouncer (
    input  clk,
    input  rst,
    input  noisy_in,
    output reg clean_out
);
    reg [3:0] counter;
    reg       stable;

    always_ff @(posedge clk) begin
        if (rst) begin
            counter    <= 4'd0;
            clean_out  <= 1'b0;
        end else begin
            if (noisy_in == clean_out) begin
                counter <= 4'd0;
            end else begin
                if (counter == 4'd15) begin
                    clean_out <= noisy_in;
                    counter   <= 4'd0;
                end else begin
                    counter <= counter + 4'd1;
                end
            end
        end
    end
endmodule

