module counter_updown_4bit (
    input        clk,
    input        rst,
    input        en,
    input        up,
    output reg [3:0] count
);
    always_ff @(posedge clk) begin
        if (rst)
            count <= 4'd0;
        else if (en) begin
            if (up)
