endmodule

module vending_machine (
    input  clk,
    input  rst,
    input  nickel,
    input  dime,
    input  quarter,
    output reg dispense,
    output reg change
);
    reg [4:0] total;  // max 30 cents

    always_ff @(posedge clk) begin
        if (rst) begin
            total   <= 5'd0;
            dispense <= 1'b0;
            change   <= 1'b0;
        end else begin
            dispense <= 1'b0;
            change   <= 1'b0;

            if (nickel) total <= total + 5'd5;
            else if (dime) total <= total + 5'd10;
            else if (quarter) total <= total + 5'd25;

            if (total >= 5'd25) begin
                dispense <= 1'b1;
                if (total > 5'd25) change <= 1'b1;
                total <= 5'd0;
            end
        end
    end
endmodule

