module spi_master (
    input        clk,
    input        rst,
    input        start,
    input  [7:0] data_in,
    output reg   mosi,
    output       sclk,
    output reg   cs_n,
    output reg [7:0] data_out,
    output reg   done
);
    reg [1:0] clk_div;
    reg [2:0] bit_cnt;
    reg [7:0] tx_reg, rx_reg;
    reg       sclk_reg;
    reg       active;

