        if (rst) begin
            clk_div  <= 2'd0;
            sclk_reg <= 1'b0;
            cs_n     <= 1'b1;
            active   <= 1'b0;
            done     <= 1'b0;
            bit_cnt  <= 3'd0;
        end else begin
            done <= 1'b0;
            if (!active && start) begin
                active  <= 1'b1;
                cs_n    <= 1'b0;
                tx_reg  <= data_in;
                bit_cnt <= 3'd0;
                clk_div <= 2'd0;
            end else if (active) begin
                clk_div <= clk_div + 2'd1;
                if (clk_div == 2'd3) begin
                    sclk_reg <= ~sclk_reg;
