                        mosi <= tx_reg[7];
                        tx_reg <= tx_reg << 1;
                        if (bit_cnt == 3'd7) begin
                            active <= 1'b0;
                            cs_n   <= 1'b1;
                            done   <= 1'b1;
                            data_out <= rx_reg;
                        end else begin
                            bit_cnt <= bit_cnt + 3'd1;
                        end
                    end
                end
            end
        end
    end

    assign sclk = sclk_reg;
endmodule

