module multiplier_4bit_array (
    input  [3:0] A, B,
    output [7:0] P
);
    wire [3:0] pp0 = A & {4{B[0]}};
    wire [3:0] pp1 = A & {4{B[1]}};
    wire [3:0] pp2 = A & {4{B[2]}};
    wire [3:0] pp3 = A & {4{B[3]}};

    wire [4:0] sum1 = pp0 + (pp1 << 1);
    wire [5:0] sum2 = sum1 + (pp2 << 2);
    wire [7:0] sum3 = sum2 + (pp3 << 3);

    assign P = sum3;
endmodule

