module uart_tx (
    input        clk,
    input        rst,
    input        tx_start,
    input  [7:0] tx_data,
    input        baud_tick,
    output reg   tx,
    output       tx_busy
);
    typedef enum logic [1:0] {IDLE, START, DATA, STOP} state_t;
    state_t state;
    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;

    always_ff @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            tx <= 1'b1;
        end else if (baud_tick) begin
            case (state)
                IDLE: begin
                    tx <= 1'b1;
                    if (tx_start) begin
                        state <= START;
                        shift_reg <= tx_data;
                    end
                end
                START: begin
                    tx <= 1'b0;
                    state <= DATA;
                    bit_cnt <= 3'd0;
                end
                DATA: begin
                    tx <= shift_reg[0];
                    shift_reg <= shift_reg >> 1;
                    if (bit_cnt == 3'd7)
                        state <= STOP;
                    else
                        bit_cnt <= bit_cnt + 3'd1;
                end
                STOP: begin
                    tx <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end

    assign tx_busy = (state != IDLE);
endmodule

module debouncer (
    input  clk,
    input  rst,
    input  noisy_in,
    output reg clean_out
);
    reg [3:0] counter;
    reg       stable;

    always_ff @(posedge clk) begin
        if (rst) begin
            counter    <= 4'd0;
            clean_out  <= 1'b0;
        end else begin
            if (noisy_in == clean_out) begin
                counter <= 4'd0;
            end else begin
                if (counter == 4'd15) begin
                    clean_out <= noisy_in;
                    counter   <= 4'd0;
                end else begin
                    counter <= counter + 4'd1;
                end
            end
        end
    end
endmodule
